<script setup lang="ts">
import axios from 'axios'
import { onBeforeUnmount,ref,watch } from 'vue'
import { useRouter } from 'vue-router'
import { ElDialog } from 'element-plus'
const props=defineProps<{conversationId?:string;runId?:string;sourceRevisionId?:string;refreshKey?:string}>()
const emit=defineEmits<{inspect:[]}>(),router=useRouter()
type Row={id:string;kind:string;status:string;conversation_id:string|null;run_id:string|null;source_revision_id:string|null;created_at:string;payload:Record<string,unknown>;actions:{id:string;kind:string;label:string;state:string}[]}
const rows=ref<Row[]>([]),next=ref<string|null>(null),busy=ref(false),error=ref(''),preview=ref<object|null>(null),previewOpen=ref(false)
type Receipt={call_id:string;state:string;usage_source?:string;synthetic?:boolean;actual_usage?:Record<string,number>;estimated_usage?:Record<string,number>;pricing?:{status?:string;amount?:string|null;currency?:string|null}}
const receipts=ref<{items:Receipt[];notice:string}|null>(null),receiptsOpen=ref(false)
const receiptStates:Record<string,string>={started:'请求已记账，尚无终态',succeeded:'已完成',failed:'失败',cancelled:'已取消',receipt_unavailable:'回执暂不可用'}
const priceStates:Record<string,string>={complete_estimate:'按价目完整估算',partial_estimate:'部分估算',user_confirmed:'用户核对金额',missing_price:'缺少价格，费用未知',unknown_usage:'用量未知，费用未知',awaiting_usage:'用量待报告，费用未知',synthetic:'合成测试，不计入真实费用',unpriced:'尚无费用估算'}
const units:Record<string,string>={input_tokens:'输入 token',output_tokens:'输出 token',cached_input_tokens:'缓存输入 token',cache_read_tokens:'缓存读取 token',requests:'请求',pages:'页',images:'图片',characters:'字符'}
function usageLabel(value?:Record<string,number>){return value&&Object.keys(value).length?Object.entries(value).map(([k,v])=>`${units[k]||k}：${v}`).join(' · '):'尚无记录'}
function checks(row:Row): {label:string;status:string}[] { return Array.isArray(row.payload.checks) ? row.payload.checks as {label:string;status:string}[] : [] }
let epoch=0,disposed=false
async function load(more=false){const token=++epoch;try{const r=await axios.get('/api/debug/records',{params:{conversation_id:props.conversationId,before_id:more?next.value:undefined}});if(!disposed&&token===epoch){rows.value=more?[...rows.value,...r.data.items]:r.data.items;next.value=r.data.next_id;error.value=''}}catch{if(!disposed&&token===epoch)error.value='诊断历史读取失败，请重试'}}
async function save(){if(busy.value)return;busy.value=true;try{await axios.post('/api/debug/records/local',{conversation_id:props.conversationId,run_id:props.runId,source_revision_id:props.sourceRevisionId});await load()}catch(e:any){error.value=e?.response?.data?.detail||'诊断记录未保存，请重试'}finally{busy.value=false}}
async function review(row:Row){try{preview.value=(await axios.get(`/api/debug/records/${row.id}/export-preview`)).data;previewOpen.value=true}catch{error.value='导出预览读取失败'}}
function download(){if(!preview.value)return;const blob=new Blob([JSON.stringify(preview.value,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='研序-脱敏诊断.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function act(row:Row,action:Row['actions'][number]){if(action.kind==='inspect_local'){emit('inspect');return}if(action.kind==='review_receipts'){try{receipts.value=(await axios.get(`/api/debug/records/${row.id}/calls`)).data;receiptsOpen.value=true}catch{error.value='调用回执读取失败，请稍后重试'}return}if(action.kind==='configure_model'){await router.push('/settings');return}if(action.kind==='open_source'&&row.source_revision_id&&row.conversation_id){await router.push({path:`/sources/${row.source_revision_id}`,query:{conversation:row.conversation_id}});return}if(action.kind==='open_run'&&row.conversation_id){await router.push({path:'/chat',query:{conv:row.conversation_id,run:row.run_id||undefined}});return}await review(row)}
async function dismiss(action:Row['actions'][number]){try{await axios.post(`/api/debug/records/actions/${action.id}/dismiss`);await load()}catch{error.value='建议状态未保存'}}
watch(()=>[props.conversationId,props.refreshKey],()=>{void load()},{immediate:true})
onBeforeUnmount(()=>{disposed=true;epoch++})
</script>
<template>
  <details class="diagnostic-history"><summary>诊断历史与安全恢复</summary><p>保存与导出只保留检查状态、错误类别和调用回执 ID，不包含密钥、文档原文、路径或原始响应。恢复建议不会自动重新执行任务。</p><div class="actions"><button :disabled="busy" @click="save">{{busy?'正在保存…':'保存一次本地检查'}}</button><button @click="load()">刷新诊断历史</button></div><p v-if="error" role="alert">{{error}}</p><p v-if="!rows.length">暂无保存的诊断。主动接口测试结束后会自动保存脱敏结果。</p><article v-for="row in rows" :key="row.id"><strong>{{row.kind==='local'?'本地检查':'主动接口测试'}} · {{row.status==='ok'?'正常':row.status==='warn'?'提示':'异常'}}</strong><small>{{row.created_at}}</small><p v-if="row.payload.detail">{{row.payload.detail}}</p><ul v-if="row.payload.checks"><li v-for="(check,index) in checks(row)" :key="index">{{check.label}} · {{check.status==='ok'?'正常':check.status==='warn'?'待检查':'异常'}}</li></ul><div v-for="action in row.actions.filter(a=>a.state==='offered')" :key="action.id" class="actions"><button @click="act(row,action)">{{action.label}}</button><button @click="dismiss(action)">忽略此建议</button></div><button @click="review(row)">审阅脱敏导出内容</button></article><button v-if="next" @click="load(true)">查看更多诊断</button></details>
  <ElDialog v-model="previewOpen" title="审阅脱敏诊断导出" width="640px"><p>确认下面内容后保存到本机。此操作不会发送给其他人，也不会运行任何恢复命令。</p><pre>{{JSON.stringify(preview,null,2)}}</pre><template #footer><button @click="previewOpen=false">关闭</button><button @click="download">保存 JSON 文件</button></template></ElDialog>
  <ElDialog v-model="receiptsOpen" title="核对调用回执与费用" width="640px"><p>{{receipts?.notice}}</p><p v-if="!receipts?.items.length">本次未找到调用回执；不能据此断言供应商没有执行或收费。</p><article v-for="call in receipts?.items" :key="call.call_id"><strong>{{receiptStates[call.state]||'状态待核对'}}{{call.synthetic?' · 合成测试':''}}</strong><small>调用编号 {{call.call_id}}</small><p>供应商报告用量：{{usageLabel(call.actual_usage)}}</p><p>估算用量：{{usageLabel(call.estimated_usage)}}</p><p>{{priceStates[call.pricing?.status||'']||'费用待核对'}}<template v-if="call.pricing?.amount!=null"> · {{call.pricing.amount}} {{call.pricing.currency}}</template></p><p>估算和用户核对记录均不代替供应商账单；确认未知结果后再决定是否重试。</p></article></ElDialog>
</template>
<style scoped>
.diagnostic-history { margin-top:16px;border-top:1px solid var(--border);padding-top:12px; }summary { cursor:pointer;font-weight:600; }p,small,li { font-size:12px;line-height:1.65;overflow-wrap:anywhere; }small { display:block;color:var(--text-2); }article { border-bottom:1px solid var(--border);padding:12px 0; }.actions { display:flex;flex-wrap:wrap;gap:6px;margin:7px 0; }button { font:inherit;font-size:12px;padding:6px 9px;border:1px solid var(--border);border-radius:6px;background:var(--card);color:var(--text);cursor:pointer; }button:focus-visible,summary:focus-visible { outline:2px solid var(--fn-brand);outline-offset:2px; }button:disabled { opacity:.5; }pre { max-height:50vh;overflow:auto;white-space:pre-wrap;font-size:11px; }ul { padding-left:18px; }
</style>
